LocalDate birthday = LocalDate.of(1990, 6, 15);
LocalDate today = LocalDate.now();
long days = ChronoUnit.DAYS.between(birthday, today);
System.out.println("Dni: " + days);

ZonedDateTime utc = ZonedDateTime.now(ZoneId.of("UTC"));
ZonedDateTime warsaw = ZonedDateTime.now(ZoneId.of("Europe/Warsaw"));
ZonedDateTime newYork = ZonedDateTime.now(ZoneId.of("America/New_York"));
System.out.println("UTC: " + utc);
System.out.println("Warszawa: " + warsaw);
System.out.println("Nowy Jork: " + newYork);

LocalDate today = LocalDate.now();
System.out.println("Pierwszy dzień: " + today.withDayOfMonth(1));
System.out.println("Ostatni dzień: " + today.withDayOfMonth(today.lengthOfMonth()));

Instant now = Instant.now();
System.out.println(now);
// Instant reprezentuje uniwersalny, jednoznaczny punkt w czasie (timestamp)
// liczony od 1 stycznia 1970 00:00 UTC (tzw. epoch) - BEZ informacji o strefie
// czasowej. Idealny do logow/baz danych, gdzie liczy się jednoznacznosc,
// nie czytelnosc dla czlowieka.

LocalDate birthday = LocalDate.of(1990, 6, 15);
LocalDate today = LocalDate.now();
long months = ChronoUnit.MONTHS.between(birthday, today);
System.out.println("Miesiecy: " + months);

LocalDate today = LocalDate.now();
System.out.println("Za 2 tygodnie: " + today.plusWeeks(2));
System.out.println("Za 3 miesiace: " + today.plusMonths(3));
System.out.println("Rok temu: " + today.minusYears(1));

LocalDate birthday = LocalDate.of(1990, 5, 15);
LocalDate today = LocalDate.now();
LocalDate nextBirthday = birthday.withYear(today.getYear());
if (nextBirthday.isBefore(today)) {
    nextBirthday = nextBirthday.plusYears(1);
}
long daysUntil = ChronoUnit.DAYS.between(today, nextBirthday);
System.out.println("Dni do urodzin: " + daysUntil);

LocalDate today = LocalDate.now();
DateTimeFormatter formatter = DateTimeFormatter.ofPattern("EEEE, d MMMM yyyy", Locale.forLanguageTag("pl"));
System.out.println(today.format(formatter));

ZonedDateTime utcTime = ZonedDateTime.now(ZoneId.of("UTC"));
ZonedDateTime tokyoTime = utcTime.withZoneSameInstant(ZoneId.of("Asia/Tokyo"));
System.out.println("UTC: " + utcTime);
System.out.println("Tokio: " + tokyoTime);

LocalDate today = LocalDate.now();
DayOfWeek day = today.getDayOfWeek();
boolean isWeekend = day == DayOfWeek.SATURDAY || day == DayOfWeek.SUNDAY;
System.out.println(isWeekend ? "Weekend!" : "Dzień roboczy");

LocalTime start = LocalTime.of(9, 0);
LocalTime end = LocalTime.of(17, 30);
long minutes = ChronoUnit.MINUTES.between(start, end);
System.out.println("Minut: " + minutes);

LocalDate d1 = LocalDate.parse("2024-12-25"); // domyślny format ISO
LocalDate d2 = LocalDate.parse("25/12/2024", DateTimeFormatter.ofPattern("dd/MM/yyyy"));
LocalDate d3 = LocalDate.parse("25.12.2024", DateTimeFormatter.ofPattern("dd.MM.yyyy"));
System.out.println(d1);
System.out.println(d2);
System.out.println(d3);

LocalDate deadline = LocalDate.of(2025, 12, 31);
LocalDate today = LocalDate.now();
if (deadline.isBefore(today)) {
    long daysAgo = ChronoUnit.DAYS.between(deadline, today);
    System.out.println("Deadline minal " + daysAgo + " dni temu");
} else {
    long daysLeft = ChronoUnit.DAYS.between(today, deadline);
    System.out.println("Pozostalo " + daysLeft + " dni");
}

LocalDate today = LocalDate.now();
for (int i = 0; i <= 14; i++) {
    LocalDate date = today.plusDays(i);
    DayOfWeek day = date.getDayOfWeek();
    if (day != DayOfWeek.SATURDAY && day != DayOfWeek.SUNDAY) {
        System.out.println(date);
    }
}

LocalDate birthDate = LocalDate.of(1990, 3, 15);
LocalDate today = LocalDate.now();
long age = ChronoUnit.YEARS.between(birthDate, today);
System.out.println("Masz " + age + " lat");

LocalDate start = LocalDate.of(2025, 1, 6);
DateTimeFormatter formatter = DateTimeFormatter.ofPattern("dd.MM.yyyy (EEEE)", Locale.forLanguageTag("pl"));
for (int i = 0; i < 8; i++) {
    LocalDate meeting = start.plusWeeks(2L * i);
    System.out.println(meeting.format(formatter));
}

